/**
 * O olho da libélula — porte de `componentes/viz/libelula.js`.
 *
 * O olho composto é uma tesselação de milhares de lentes hexagonais — os
 * omatídios —, e cada uma enxerga UM ponto. A imagem é o mosaico que sai da soma
 * delas, o que explica de uma vez por que mais facetas significam mais nitidez:
 * é a mesma coisa que ter mais pixels.
 *
 * Por isso a cena desenha o mosaico de verdade e borra a presa por cima: a mosca
 * vai ficando nítida à medida que as facetas se multiplicam.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import { type EstadoDaViz, infoDe, limitar, numeroDe, paleta, rodape, titulo } from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

const libelula: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** A cor que uma faceta capta na posição normalizada — o "pixel" dela. */
  function corDaPresa(nx: number, ny: number): string {
    const d = Math.hypot(nx, ny - 0.05);
    if (d < 0.42) return '#6ed28c';
    if (Math.abs(ny) < 0.16 && Math.abs(nx) < 0.8) return '#96d2ff';
    return '#c3cbe8';
  }

  function hexagono(ctx: CanvasRenderingContext2D, x: number, y: number, r: number): void {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = Math.PI / 6 + (i * Math.PI) / 3;
      const px = x + r * Math.cos(a);
      const py = y + r * Math.sin(a);
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const facetas = Math.max(1, numeroDe(valores, 'f', 1));
    const ok = info.ok === true;
    const nitidez = limitar(numeroDe(info, 'nitidez', 0), 0, 100);

    const cx = L / 2;
    const cy = A * 0.5;
    const R = Math.min(L, A) * 0.36;

    titulo(ctx, L, A, 'Cada lente enxerga um ponto');

    // O mosaico. Mais facetas = hexágonos menores = mais "pixels" no olho.
    const colunas = Math.round(3 + (facetas / 100) * 26);
    const hr = R / colunas;
    const dx = hr * 1.5;
    const dy = hr * Math.sqrt(3);

    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.clip();

    for (let c = -colunas - 1; c <= colunas + 1; c++) {
      for (let r = -colunas - 1; r <= colunas + 1; r++) {
        const x = cx + c * dx;
        const y = cy + r * dy + (Math.abs(c % 2) === 1 ? dy / 2 : 0);
        const nx = (x - cx) / R;
        const ny = (y - cy) / R;
        if (nx * nx + ny * ny > 1.05) continue;

        ctx.fillStyle = corDaPresa(nx, ny);
        hexagono(ctx, x, y, hr * 0.96);
        ctx.fill();
        ctx.strokeStyle = cor.trilho;
        ctx.lineWidth = 0.5;
        ctx.stroke();
      }
    }

    // A presa por cima, borrada na medida da nitidez que o mosaico entrega.
    const desfoque = ok ? 0 : Math.min(15, (100 - nitidez) * 0.16);
    ctx.lineJoin = 'round';
    ctx.filter = desfoque > 0.1 ? `blur(${desfoque.toFixed(1)}px)` : 'none';

    const corpoY = cy + 0.05 * R;

    ctx.fillStyle = 'rgb(150 210 255 / 55%)';
    ctx.strokeStyle = cor.contraste;
    ctx.lineWidth = 2;
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.ellipse(
        cx + lado * 0.5 * R,
        cy - 0.02 * R,
        0.34 * R,
        0.14 * R,
        lado * 0.25,
        0,
        Math.PI * 2,
      );
      ctx.fill();
      ctx.stroke();
    }

    ctx.beginPath();
    ctx.ellipse(cx, corpoY, 0.42 * R, 0.42 * R, 0, 0, Math.PI * 2);
    ctx.fillStyle = ok ? cor.verde : '#6ed28c';
    ctx.fill();
    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 4;
    ctx.stroke();
    ctx.strokeStyle = ok ? cor.verde : cor.contraste;
    ctx.lineWidth = 2.2;
    ctx.stroke();

    ctx.fillStyle = cor.texto;
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.arc(cx + lado * 0.16 * R, corpoY - 0.22 * R, 0.07 * R, 0, Math.PI * 2);
      ctx.fill();
    }

    ctx.filter = 'none';
    ctx.restore();

    ctx.strokeStyle = ok ? cor.verde : cor.fraco;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(cx, cy, R, 0, Math.PI * 2);
    ctx.stroke();

    rodape(
      ctx,
      L,
      A,
      ok,
      'Visão nítida: dá para ver a mosca ✔',
      `${colunas * colunas} facetas — a imagem ainda é grosseira.`,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A }) => desenhar(ctx, L, A),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default libelula;
